<template>
  <div>
    <el-table
      size="mini"
      :data="attributeList"
      style="width: 100%"
      v-loading="loading"
    >
      <el-table-column prop="describe" label="通道名称" align="center" />
      <el-table-column prop="channel_id" label="通道编号" align="center">
        <template slot-scope="scope">
          {{
            scope.row.protocol_config
              ? scope.row.protocol_config.channel_id
              : ""
          }}
        </template>
      </el-table-column>
      <el-table-column label="报警事件" align="center">
        <template slot-scope="scope">
          <el-button
            type="text"
            v-if="scope.row.analysisData"
            @click="
              getDataAiValueList(
                scope.row.analysisData,
                scope.row.analysisData[0].is_alarm
              )
            "
          >
            <span
              v-for="(item, index) in JSON.parse(
                scope.row.analysisData[0].ai_value
              )"
              :key="index"
            >
              {{ item.ai_name }}
            </span>
          </el-button>
          <!-- <el-button
            type="text"
            v-if="scope.row.analysisData"
            @click="
              getDataAiValueList(
                scope.row.analysisData,
                scope.row.analysisData[0].is_alarm
              )
            "
            >{{
              JSON.parse(scope.row.analysisData[0].ai_value).ai_name
            }}</el-button
          > -->
        </template>
      </el-table-column>
      <el-table-column
        prop="protocol_config.interval_time"
        label="拍照时间间隔（秒）"
        align="center"
      >
        <template slot-scope="scope">
          {{
            scope.row.protocol_config
              ? scope.row.protocol_config.interval_time
              : ""
          }}
        </template>
      </el-table-column>
      <el-table-column prop="ai_file" label="报警图片" align="center">
        <template slot-scope="scope">
          <el-image
            v-if="
              scope.row.analysisData && scope.row.analysisData[0].ai_file !== ''
            "
            style="width: 100px; height: 80px"
            :src="scope.row.analysisData[0].ai_file"
            :preview-src-list="[scope.row.analysisData[0].ai_file]"
            fit="fill"
            referrerpolicy="no-referrer"
          >
          </el-image>
          <span v-else>暂无图片</span>
        </template>
      </el-table-column>
      <el-table-column prop="base_value" label="最新图片" align="center">
        <template slot-scope="scope">
          <el-image
            v-if="scope.row.base_value"
            style="width: 100px; height: 80px"
            :src="scope.row.base_value"
            :preview-src-list="[scope.row.base_value]"
            fit="fill"
            referrerpolicy="no-referrer"
          >
          </el-image>
          <span v-else>暂无图片</span>
        </template>
      </el-table-column>
      <el-table-column label="操作" align="center">
        <template slot-scope="scope">
          <el-button type="text" @click="editAttribute(scope.row)">
            <i title="编辑" class="el-icon-edit"></i>
          </el-button>
          <el-button type="text" @click="configure(scope.row)"
            ><i title="AI配置">AI</i>
          </el-button>
          <el-button type="text" @click="goPage(scope.row)"
            ><i title="记录" class="el-icon-tickets"></i>
          </el-button>
          <el-button type="text" @click="getVideo(scope.row)"
            ><i title="视频" class="el-icon-video-play"></i>
          </el-button>
          <el-button type="text" @click="delAttribute(scope.row)">
            <i title="删除" class="el-icon-delete" style="color: red"></i>
          </el-button>
        </template>
      </el-table-column>
    </el-table>

    <el-dialog title="分析列表" width="40%" :visible.sync="aiValueVisible">
      <el-table :data="AiValueList">
        <el-table-column label="报警图片" align="center" prop="ai_file">
          <template slot-scope="scope">
            <el-image
              v-if="scope.row.ai_file"
              style="width: 100px; height: 100px"
              :src="`${scope.row.ai_file}`"
              :preview-src-list="[`${scope.row.ai_file}`]"
              fit="fill"
              referrerpolicy="no-referrer"
            >
            </el-image>
            <span v-else>暂无图片</span>
          </template>
        </el-table-column>
        <el-table-column label="报警时间" align="center" prop="create_time" />
        <el-table-column label="事件名称" align="center">
          <template slot-scope="scope">
            <div
              v-for="(item, index) in JSON.parse(scope.row.ai_value)"
              :key="index"
            >
              <el-popover placement="top" width="200" trigger="hover">
                <div
                  v-for="(sitem, sindex) in item.ai_class"
                  :key="'detail_' + sindex"
                  style="text-align: center"
                >
                  {{ sitem.name }}: {{ sitem.confidence | toFixed }}
                </div>
                <el-button slot="reference" type="text">
                  {{ item.ai_name }}</el-button
                >
              </el-popover>
            </div>
          </template>
        </el-table-column>
      </el-table>
    </el-dialog>
    <!-- 属性 -->
    <el-dialog
      :title="attributeVisibleTitle"
      :visible.sync="attributeVisible"
      width="40%"
      :close-on-click-modal="false"
    >
      <el-form
        :model="attributeForm"
        :rules="rules"
        ref="attributeForm"
        label-width="200px"
        size="small"
        style="width: 80%"
      >
        <el-form-item label="通道名称:" prop="describe">
          <el-input v-model="attributeForm.describe"></el-input>
        </el-form-item>
        <el-form-item label="通道编号:" prop="channel_id">
          <el-input
            v-model="attributeForm.protocol_config.channel_id"
          ></el-input>
        </el-form-item>
        <el-form-item label="视频流地址:" prop="stream_url">
          <el-input
            v-model="attributeForm.protocol_config.stream_url"
          ></el-input>
        </el-form-item>
        <el-form-item label="启用抓拍">
          <el-switch
            v-model="attributeForm.protocol_config.is_snap"
            :active-value="1"
            :inactive-value="2"
          ></el-switch>
        </el-form-item>
        <el-form-item label="拍照时间间隔(秒):">
          <el-input-number
            :disabled="attributeForm.protocol_config.is_snap == 2"
            v-model="attributeForm.protocol_config.interval_time"
            :min="60"
          >
          </el-input-number>
        </el-form-item>
        <el-form-item label="预览视频流分析">
          <el-switch
            v-model="attributeForm.protocol_config.is_preview_analysis"
            :active-value="1"
            :inactive-value="2"
          ></el-switch>
        </el-form-item>
      </el-form>

      <span slot="footer" class="dialog-footer">
        <el-button @click="attributeVisible = false">取 消</el-button>
        <el-button type="primary" @click="submitAttributeForm('attributeForm')"
          >确 定</el-button
        >
      </span>
    </el-dialog>
    <el-dialog
      title="视频"
      width="60%"
      :visible.sync="videoVisible"
      v-if="videoVisible"
      top="20px"
    >
      <div style="width: 100%; background: #000">
        <videoPlayer
          :src="videoUrl"
          v-if="videoVisible"
          @closeVideo="closeVideo"
        ></videoPlayer>
      </div>
    </el-dialog>
  </div>
</template>

<script>
import videoPlayer from "@/components/videoPlayer.vue";
import { getUrl } from "@/assets/utils/config";

export default {
  props: {
    chooseItem: {
      type: Object,
      default: () => ({}),
    },
    sourceTab: {
      type: Number,
    },
    attributeList: {
      type: Array,
      default: () => [],
    },
  },
  components: {
    videoPlayer,
  },
  data() {
    return {
      loading: false,
      attributeParams: {
        page: 1,
        size: 10,
      },
      timer: null,
      attributeTotal: 0,
      aiValueVisible: false,
      queryParams: {
        page: 1,
        size: 10,
      },
      AiList: [],
      aitotal: 0,
      AiPropertyList: [],
      AiValueList: [],
      attributeVisible: false,
      attributeForm: {
        protocol_config: {},
      },
      attributeVisibleTitle: "",
      rules: {},
      selectedItems: [],
      videoVisible: false,
      videoUrl: "",
    };
  },
  watch: {
    chooseItem: {
      handler(val) {
        if (val.source_id) {
          this.chooseItemInfo = { ...val };
          // this.getAttributeList();
        }
      },
      deep: true,
      immediate: true,
    },
  },
  filters: {
    toFixed(value) {
      return parseFloat(value).toFixed(2);
    },
  },
  created() {
    this.chooseItemInfo = { ...this.chooseItem };
  },
  methods: {
    // 关闭弹窗
    closeVisible() {
      this.attributeVisible = false;
    },
    closeVideo() {
      this.$api
        .get("/media/stopPlay", { params: { id: this.aiItem.id } })
        .then(() => {
          this.$message.success("视频流已关闭");
        });
    },
    getVideo(row) {
      this.aiItem = row;
      let addr = "/media/play";
      this.$api.get(addr, { params: { id: this.aiItem.id } }).then((res) => {
        if (res.data.data.play_url) {
          this.videoUrl = getUrl(res.data.data.play_url);
          // this.videoUrl = res.data.data.play_url.replace(
          //   "127.0.0.1",
          //   "192.168.0.202"
          // );
          this.videoVisible = true;
        } else {
          this.$message.warning("操作成功");
        }
      });
    },
    getDataAiValueList(row) {
      this.AiValueList = row;
      this.aiValueVisible = true;
    },
    addAttribute() {
      this.attributeVisibleTitle = "添加属性";
      this.attributeForm = {
        source_id: this.chooseItemInfo.source_id,
        protocol_config: {
          interval_time: 5 * 60,
          is_snap: 2,
        },
      };
      this.attributeVisible = true;
    },
    handleSelectAll() {},
    handleChange(val) {
      this.selectedItems = val;
    },
    handleSelect() {},
    delAttribute(item) {
      this.$emit("delectItem", item);
    },
    goPage(row) {
      this.$router.push({
        path: "/historicalRecords/imageAnalysis",
        query: { pro_id: row.id, source_id: this.chooseItem.source_id },
      });
    },
    configure(item) {
      this.aiItem = item;
      this.AiPropertyList = [];
      this.selectedItems = [];
      this.$router.push({
        path: "/collection/AIConfig",
        query: {
          pro_id: item.id,
          sourceTab: this.sourceTab,
          source_id: this.chooseItem.source_id,
          page: this.chooseItem.page,
        },
      });
    },
    // 新增属性提交
    submitAttributeForm(formName) {
      this.$refs[formName].validate((valid) => {
        if (valid) {
          this.$emit("saveAttribute", this.attributeForm);
        } else {
          return false;
        }
      });
    },
    // 编辑属性
    editAttribute(row) {
      this.attributeVisibleTitle = "编辑属性";
      this.attributeForm = { ...row };
      this.attributeForm.protocol_config = !this.analyzeProperty(
        row.protocol_config
      )
        ? {}
        : {
            ...row.protocol_config,
            interval_time: row.protocol_config.interval_time || 5 * 60,
          };
      this.attributeVisible = true;
    },

    analyzeProperty(value) {
      if (
        value === null ||
        value === "null" ||
        value === "" ||
        value === undefined
      )
        return false;

      if (typeof value === "object" && value !== null) {
        if (Object.keys(value).length === 0) return false;
      }
      return true;
    },
  },
};
</script>

<style lang="scss" scoped></style>
